using System.Linq;using UnityEditor;using UnityEngine;using AntColony.Units;
public static class FurnitureUse1114Library {public static string Run(){foreach(var path in new[]{"MeshyNative/Library","MeshyNative/Runtime"}){var lib=Resources.Load<MeshyNativeLibrary>(path);foreach(var action in new[]{"ReadBook","Saw"})lib.actions=lib.actions.Where(a=>a.action!=action).Concat(new[]{new MeshyNativeLibrary.ActionBinding{action=action,motion="Idle_3"}}).ToArray();EditorUtility.SetDirty(lib);}AssetDatabase.SaveAssets();return "Existing Idle_3 native body with furniture hand corrections bound to ReadBook/Saw";}}
